---@class RegressionDojo
local RegressionDojo = Class("RegressionDojo")

function RegressionDojo:__init()
    ---@ 任务信息
    self.taskInfo = {}    --{task 任务列表  taskBox 任务宝箱信息}
    ---@ 大富翁信息
    self.jackpotInfo = {}
    ---@ 累计登录信息
    self.accumulateLoginInfo = {}
    ---@ 礼包信息
    self.mall = {}
	---@ 组别ID
	self.groupId = 0
	---@ 开始时间
	self.startTime = 0
	---@ 关闭时间
	self.closeTime = 0
end

---FillVo
---@param jsonData table
function RegressionDojo:Fill(jsonData)
	jsonData = checkTable(jsonData)
	for key, value in pairs(jsonData) do
		--只更新自己关心的数据
		if isSet(jsonData, key) and table.haskey(self, key) then
			self[key] = value
		end
	end
	
	if isSet(self,"mall") then
		for i, v in pairs(self.mall.products) do
			self:ConvertPrices(v)
		end
	end
end

---将prices转为需要的格式
function RegressionDojo:ConvertPrices(data)
	if not data.prices then return end
	local prices = {}
	for k, v in pairs(checkTable(data.prices)) do
		local tmp = {}
		tmp.current = v.current
		tmp.original = v.original
		tmp.currency = tonumber(k)
		table.insert(prices, tmp)
	end
	data.prices = prices
end

function RegressionDojo:GetJackPotInfo()
    return self.jackpotInfo
end

function RegressionDojo:UpdateJackPotInfo(info)
	self.jackpotInfo.nowStep = info.nowStep
	self.jackpotInfo.nowRound = info.nowRound
end

function RegressionDojo:GetDailySignInfo()
	return self.accumulateLoginInfo
end

function RegressionDojo:GetGiftInfo()
	return self.mall
end

function RegressionDojo:__delete()
    ---@ 任务信息
    self.taskInfo = nil
    ---@ 大富翁信息
    self.jackpotInfo = nil
    ---@ 累计登录信息
    self.accumulateLoginInfo = nil
    ---@ 礼包信息
    self.mall = nil
	---@ 组别ID
	self.groupId = nil
	---@ 开始时间
	self.startTime = nil
	---@ 关闭时间
	self.closeTime = nil
end

return RegressionDojo